window.SPARK_APP = {"name": "PRISM - SPARK", "version": "1.8.0"};
window.SPARK_BANK = {"version":"1.4","thresholds":{"negativeShare":0.3,"minNegatives":2,"goodScore":70,"maxUnprovenForGood":3,"failedStagesForRed":3,"buttonMaxOptions":5,"ratingRedMax":39,"ratingYellowMax":69,"tooEarlyGateShare":0.5},"stages":[{"id":1,"title":"Define the idea","short":"Define the idea","weight":0,"core":false,"scored":false,"purpose":"First, understand what the entrepreneur believes they are creating.","objective":"Establish a clear hypothesis without assuming it is correct.","gate":"Proceed when the idea fits in three sentences and the assumptions behind it are written down.","nextStep":"Write the idea in three sentences and list the assumptions behind it."},{"id":2,"title":"Establish founder fit and personal goals","short":"Founder fit and goals","weight":8,"core":false,"scored":true,"purpose":"Determine what the entrepreneur needs from the business, so every later stage is judged against that standard.","objective":"Establish whether this is the right idea for this entrepreneur, not only whether it is a good idea.","gate":"Proceed when you can state what you need from the business, and the time and money you are prepared to risk finding out.","nextStep":"Write down what you need from the business and the time and money you will risk to find out.","selfReport":true},{"id":3,"title":"Identify the problem","short":"Identify the problem","weight":12,"core":true,"scored":true,"purpose":"Determine whether a real problem exists independently of the proposed solution.","objective":"Establish that the problem is real, consequential and experienced by identifiable people.","gate":"Proceed when you can say who has the problem, how often and what it costs them, with at least one piece of evidence that is not your own opinion.","nextStep":"Collect one piece of evidence that someone other than you has this problem: a complaint, a workaround or money spent."},{"id":4,"title":"Understand the customer","short":"Understand the customer","weight":8,"core":true,"scored":true,"purpose":"Determine exactly who experiences the problem and why it matters to them.","objective":"Identify a specific initial customer segment rather than targeting everyone who might conceivably benefit.","gate":"Proceed when you can describe one segment precisely and list at least 20 real people or organisations in it that you can contact.","nextStep":"List 20 named people or organisations in one segment that you could contact this month."},{"id":5,"title":"Validate the problem with real people","short":"Validate the problem","weight":12,"core":true,"scored":true,"purpose":"Test the entrepreneur's assumptions through customer discovery before pitching the idea.","objective":"Determine whether independent customer evidence supports the problem hypothesis.","gate":"Proceed when at least 15 conversations show a consistent pattern, and most people can describe a recent occasion and what they did about it.","nextStep":"Interview 15 people in the segment about the last time the problem occurred and what they did."},{"id":6,"title":"Assess existing alternatives and competition","short":"Alternatives and competition","weight":6,"core":false,"scored":true,"purpose":"Determine whether the problem is already adequately addressed.","objective":"Identify a genuine opportunity in the market, not merely a product that is different.","gate":"Proceed when you can explain why a customer would switch from their current option, using evidence from customer conversations rather than a feature comparison.","nextStep":"Ask five customers what they use today and what would make them switch, then compare the answers with your difference."},{"id":7,"title":"Test the timing","short":"Timing","weight":4,"core":false,"scored":true,"purpose":"Determine why this opportunity exists now and whether the window is opening or closing.","objective":"Establish that the timing is right, rather than assuming a good idea is good at any time.","gate":"Proceed when you can point to a specific change that makes this viable now, and explain why earlier attempts fell short.","nextStep":"Name the specific change that makes this viable now and find out why earlier attempts stalled."},{"id":8,"title":"Define and test the proposed solution","short":"Test the solution","weight":8,"core":true,"scored":true,"purpose":"Only after establishing the problem should the entrepreneur test how to solve it.","objective":"Find the simplest credible way to test whether the proposed solution delivers meaningful value.","gate":"Proceed when potential customers shown a prototype or pilot understand the value without coaching and can say what it would replace.","nextStep":"Show a mock-up or prototype to five customers without explaining it, and note whether they can say what it would replace."},{"id":9,"title":"Test willingness to adopt and pay","short":"Willingness to pay","weight":12,"core":true,"scored":true,"purpose":"Determine whether the opportunity has commercial substance.","objective":"Distinguish stated interest from demonstrated willingness to commit resources.","gate":"Proceed when at least three customers have made a real commitment: a paid pilot, deposit, purchase order or signed agreement.","nextStep":"Ask for a paid pilot, deposit, purchase order or signed agreement from your most interested prospects."},{"id":10,"title":"Confirm the value was delivered","short":"Value delivered","weight":5,"core":false,"scored":true,"purpose":"Determine whether the first customers got the result they were promised, rather than assuming a sale proves the solution works.","objective":"Establish that the solution works in customers' hands, not only that they were willing to try it.","gate":"Proceed when most pilot customers achieved the promised outcome, and at least one has renewed, bought again or referred someone.","nextStep":"Measure whether your pilot customers got the promised outcome, then ask each to renew, buy again or refer someone."},{"id":11,"title":"Validate the route to customers","short":"Route to customers","weight":7,"core":false,"scored":true,"purpose":"Test whether customers can be reached repeatedly and affordably, rather than assuming a channel will work.","objective":"Establish that there is a tested, repeatable way to reach customers, not only a product they would buy.","gate":"Proceed when a small channel test has produced qualified conversations at a cost the business model can support.","nextStep":"Run a small test of your main channel and work out the cost per qualified conversation."},{"id":12,"title":"Assess the market opportunity","short":"Market opportunity","weight":5,"core":false,"scored":true,"purpose":"Determine whether the idea could support a viable business.","objective":"Establish whether there is a reachable market large enough to justify the opportunity.","gate":"Proceed when the reachable market, at realistic prices and market share, would meet the goals set in Stage 2.","nextStep":"Count the customers you can realistically reach and check that, at a moderate share, they meet your Stage 2 goals."},{"id":13,"title":"Test the business model and economics","short":"Business model","weight":6,"core":false,"scored":true,"purpose":"Determine whether the entrepreneur can create and capture enough value to sustain the business.","objective":"Determine whether the opportunity has credible, sustainable economics.","gate":"Proceed when the business covers its costs under conservative assumptions, and a customer is worth about three times what they cost to acquire, and the funding to reach that point has a realistic source.","nextStep":"Build a one-page model: cost to deliver, acquisition cost, customer value and funding, then test it with a 20% miss on each input."},{"id":14,"title":"Assess the entrepreneur's ability to execute","short":"Ability to execute","weight":5,"core":false,"scored":true,"purpose":"Determine whether the entrepreneur can realistically turn the opportunity into a business.","objective":"Establish a credible path from idea to execution within the entrepreneur's actual constraints.","gate":"Proceed when the first version can be built and delivered within the time and money set in Stage 2, with no unresolved ownership or legal barrier.","nextStep":"Cost the first version against your Stage 2 limits and confirm in writing that you own the idea."},{"id":15,"title":"Evaluate long-term potential and defensibility","short":"Defensibility","weight":2,"core":false,"scored":true,"purpose":"Once initial evidence supports the idea, determine whether it can become a durable business.","objective":"Assess whether the idea has the potential to develop into a sustainable competitive position, rather than assuming defensibility exists from day one.","gate":"Proceed when you can name at least one advantage that should strengthen as the business grows, and no single dependency could end the business.","nextStep":"Name the advantage that should strengthen as you grow, and find a fallback for any single dependency."},{"id":16,"title":"Make the decision","short":"Make the decision","weight":0,"core":false,"scored":false,"purpose":"Determine whether to proceed, test further, change direction or abandon the idea.","objective":"Make a decision based on evidence rather than enthusiasm, sunk costs or attachment to the original idea.","gate":"","nextStep":"Pick the riskiest assumption and design the cheapest experiment that could disprove it."}],"questions":[{"id":1,"stage":1,"type":"T","label":"The idea","short":"Describe your idea in two or three sentences.","text":"What is your idea? Describe it in two or three sentences.","placeholder":"e.g. A booking service that lets dog groomers fill last-minute cancellations."},{"id":2,"stage":1,"type":"T","label":"What it does for people","short":"What will it do for people?","text":"What do you believe it will do for people?","placeholder":"e.g. Groomers stop losing a day's income to no-shows."},{"id":3,"stage":1,"type":"T","label":"First beneficiaries","short":"Who do you think would benefit most?","text":"Who do you initially believe would benefit most from it?","placeholder":"e.g. Independent groomers with one or two chairs."},{"id":4,"stage":1,"type":"C","label":"Origin of the idea","short":"What made you think of this idea?","text":"What made you think of this idea?","options":[{"id":"a","text":"My own frustration with the problem"},{"id":"b","text":"Something I saw at work"},{"id":"c","text":"Customers or clients asked for it"},{"id":"d","text":"Research or reading"},{"id":"e","text":"A conversation with someone"},{"id":"f","text":"A technology or trend I noticed"},{"id":"g","text":"Something else"}]},{"id":5,"stage":1,"type":"C","label":"Basis for potential","short":"What makes you believe it has potential?","text":"What have you observed, experienced or learned that led you to believe this idea has potential?","options":[{"id":"a","text":"A gut feeling"},{"id":"b","text":"My own experience"},{"id":"c","text":"I've seen others struggle with it"},{"id":"d","text":"People told me they want it"},{"id":"e","text":"People already pay for something similar"},{"id":"f","text":"Data or research"}]},{"id":6,"stage":1,"type":"T","label":"Assumptions","short":"What are you assuming about the idea?","text":"What assumptions are you currently making about the idea?","placeholder":"e.g. Groomers lose at least two bookings a week and would pay to recover them."},{"id":7,"stage":2,"type":"S","label":"Goal for the business","short":"What do you most want this business to give you?","text":"What do you want this business to give you: income, independence, a saleable asset or scale?","quick":true,"weight":2,"gateMin":2,"gateText":"A goal is chosen","action":"Decide what you most want the business to give you","options":[{"id":"a","text":"Not decided yet","tag":"U","points":0},{"id":"b","text":"Income","points":2},{"id":"c","text":"Independence","points":2},{"id":"d","text":"A saleable asset or scale","points":2},{"id":"f","text":"One of these, with a number and a date","points":3}],"why":"A goal with a number and a date (for example, $8,000 a month within 18 months) is what later stages are judged against.","basis":"Camuffo et al. (2020), Management Science: state hypotheses and test them; a goal with a number and a date can be tested later","howTo":"Write one sentence with what you want, a number and a date, for example \"$8,000 a month within 18 months\".","success":"A written goal with a number and a date","time":"1 hour"},{"id":8,"stage":2,"type":"S","label":"Financial runway","short":"How many months can your household go without income from this?","text":"How much financial risk can you and your household absorb, and how long can you go without income from this business?","quick":true,"weight":2,"gateMin":2,"gateText":"The income gap is worked out","action":"Work out how long your household can go without income from the business","options":[{"id":"a","text":"Not worked out","tag":"U","points":0},{"id":"b","text":"A rough guess, not calculated","tag":"U","points":0},{"id":"g","text":"Less than 3 months, calculated","points":1},{"id":"h","text":"3 to 12 months, calculated","points":2},{"id":"i","text":"More than 12 months, calculated","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers","howTo":"List your household's monthly costs and savings, then divide savings by the monthly gap this venture creates.","success":"Runway in months, calculated","time":"1–2 hours"},{"id":9,"stage":2,"type":"S","label":"Founder advantage","short":"How much experience do you have in this industry?","text":"Why are you better placed than anyone else to pursue this idea?","quick":false,"weight":1,"options":[{"id":"a","text":"Haven't thought about it","tag":"U","points":0},{"id":"b","text":"No relevant experience or contacts","tag":"N","points":0},{"id":"c","text":"Interest in the area, but no work experience in it","points":1},{"id":"d","text":"Under 3 years working in this industry","points":2},{"id":"e","text":"3 or more years in this industry, with customer contacts","points":3}],"basis":"Azoulay, Jones, Kim & Miranda (2020), AER: Insights: 3+ years in the same industry roughly doubles top-tier success"},{"id":10,"stage":2,"type":"S","label":"Five-year commitment","short":"Would you still want to work on this problem in five years?","text":"Would you still want to work on this problem in five years?","quick":false,"weight":1,"options":[{"id":"a","text":"Not sure yet","tag":"U","points":0},{"id":"b","text":"Probably not","tag":"N","points":0},{"id":"c","text":"Probably","points":2},{"id":"d","text":"Yes, definitely","points":3}]},{"id":11,"stage":3,"type":"T","label":"The problem","short":"What specific problem are you solving?","text":"What specific problem are you trying to solve?","placeholder":"e.g. Last-minute cancellations leave groomers with empty, unpaid slots."},{"id":12,"stage":3,"type":"T","label":"Who has it most","short":"Who experiences this problem most acutely?","text":"Who experiences this problem most acutely?","placeholder":"e.g. Solo groomers who rent their chair by the day."},{"id":13,"stage":3,"type":"S","label":"When the problem occurs","short":"Can you say when and where the problem occurs?","text":"When, where and under what circumstances does the problem occur?","quick":false,"weight":1,"options":[{"id":"a","text":"Not sure yet","tag":"U","points":0},{"id":"b","text":"Only in general terms","points":1},{"id":"c","text":"In a few typical situations people described","points":2},{"id":"d","text":"A specific trigger that people describe the same way","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":14,"stage":3,"type":"S","label":"How often it occurs","short":"How often does the problem occur for them?","text":"How frequently does it occur?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know yet","tag":"U","points":0},{"id":"b","text":"Rarely: once a year or less","tag":"N","points":0},{"id":"c","text":"A few times a year","points":1},{"id":"d","text":"Monthly","points":2},{"id":"e","text":"Weekly or more","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":15,"stage":3,"type":"S","label":"Current way of coping","short":"Do you know how people deal with it today?","text":"How do people currently deal with it?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know yet","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"e","text":"From desk research or online reviews","points":1},{"id":"c","text":"People described what they did last time","points":2},{"id":"d","text":"I've watched them do it, or seen what they paid","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":16,"stage":3,"type":"S","label":"Cost of the problem","short":"What does the problem cost them?","text":"What does the problem cost them in money, time, effort, missed opportunities or frustration?","quick":false,"weight":1,"options":[{"id":"a","text":"Not estimated","tag":"U","points":0},{"id":"b","text":"Little or nothing","tag":"N","points":0},{"id":"c","text":"An annoyance, with no measurable cost","points":1},{"id":"d","text":"A measurable cost in time or money","points":2},{"id":"e","text":"Severe, and they can put a number on it","points":3}],"basis":"Blank, The Four Steps to the Epiphany: earlyvangelist ladder (has the problem, knows it, is looking, has a stopgap, has budget)"},{"id":17,"stage":3,"type":"S","label":"Cost of doing nothing","short":"What happens if they do nothing about it?","text":"What happens if they do nothing about it?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Nothing much","tag":"N","points":0},{"id":"c","text":"It gets slightly worse","points":1},{"id":"d","text":"Losses keep adding up","points":2},{"id":"e","text":"Serious harm or a lost opportunity they can name","points":3}]},{"id":18,"stage":3,"type":"S","label":"Urgency","short":"How far have people gone to solve it?","text":"Is this a problem people actively want to solve, or simply something they would prefer to be better?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know yet","tag":"U","points":0},{"id":"b","text":"They don't see it as a problem","tag":"N","points":0},{"id":"f","text":"They know about it, but aren't looking for a fix","points":1},{"id":"g","text":"They're actively looking for a fix","points":2},{"id":"h","text":"They've built a stopgap or set aside budget for it","points":3}],"basis":"Blank, The Four Steps to the Epiphany: earlyvangelist ladder (has the problem, knows it, is looking, has a stopgap, has budget)"},{"id":19,"stage":3,"type":"S","label":"Evidence the problem exists","short":"What evidence do you have that the problem exists?","text":"What evidence do you have that this problem actually exists beyond your own opinion?","why":"Opinion alone cannot pass a stage; the evidence must come from what other people have said or done.","quick":true,"weight":2,"gateMin":2,"gateText":"Evidence beyond your own experience","action":"Find evidence beyond your own experience that the problem exists","options":[{"id":"a","text":"None gathered yet","tag":"U","points":0},{"id":"b","text":"I looked and found little sign of it","tag":"N","points":0},{"id":"c","text":"Only my own experience so far","tag":"U","points":0},{"id":"d","text":"Others described a recent time it happened to them","points":2},{"id":"e","text":"Others have spent money or time on it","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment); Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money","howTo":"Find five people who have the problem and ask about the last time it happened, not whether they like your idea.","success":"At least three describe a recent, specific occasion","time":"1 week"},{"id":20,"stage":4,"type":"T","label":"Target customer","short":"Who is the specific person or organisation most affected?","text":"Who is the specific person or organisation most affected by this problem?","placeholder":"e.g. Solo dog groomers in Calgary with 20+ bookings a week."},{"id":21,"stage":4,"type":"S","label":"Segment definition","short":"Can you say what sets these customers apart from everyone else?","text":"What characteristics distinguish these people from everyone else?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Broadly, such as 'small businesses'","points":1},{"id":"c","text":"Two or three clear traits","points":2},{"id":"d","text":"Precisely enough to pick them out of a list","points":3}]},{"id":22,"stage":4,"type":"S","label":"Who feels it most","short":"Do you know who feels the greatest pain or cost?","text":"Who experiences the greatest pain or financial impact?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"c","text":"A group, from what people told me","points":2},{"id":"d","text":"A group, confirmed by what they spend or do","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":23,"stage":4,"type":"S","label":"Most motivated buyers","short":"Do you know who is most motivated to find a solution?","text":"Who is most motivated to find a solution?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"e","text":"A group that is actively looking for a fix","points":2},{"id":"f","text":"A group that already has a stopgap or budget","points":3}],"basis":"Blank, The Four Steps to the Epiphany: earlyvangelist ladder (has the problem, knows it, is looking, has a stopgap, has budget)"},{"id":24,"stage":4,"type":"S","label":"User, payer and decider","short":"Do you know who would use it, who pays and who decides?","text":"Who would use a solution, who would pay for it, and who would make the purchasing decision?","quick":false,"weight":1,"options":[{"id":"a","text":"Not worked out","tag":"U","points":0},{"id":"b","text":"They differ and pull in different directions","tag":"N","points":0},{"id":"c","text":"Partly known","points":1},{"id":"f","text":"All three known by role","points":2},{"id":"g","text":"All three known by name, and they agree","points":3}],"basis":"Webster & Wind (1972): the buying centre (users, payers, deciders)"},{"id":25,"stage":4,"type":"S","label":"How they find solutions","short":"Do you know how they discover and evaluate solutions?","text":"How do these people currently discover and evaluate solutions?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"c","text":"Several people told me how they search","points":2},{"id":"d","text":"I've seen where they actually looked or bought","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":26,"stage":4,"type":"S","label":"Reachable prospects","short":"How many real prospects in this segment could you contact?","text":"Can you readily identify and reach a group of these potential customers?","quick":true,"weight":2,"gateMin":3,"gateText":"At least 20 named prospects","action":"List at least 20 named prospects you can contact","options":[{"id":"a","text":"Haven't listed any","tag":"U","points":0},{"id":"b","text":"They're hard to find or reach","tag":"N","points":0},{"id":"c","text":"Fewer than 10","points":1},{"id":"d","text":"10 to 19","points":2},{"id":"e","text":"20 or more, named","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers","howTo":"Build a list of 20 named people or organisations in one segment, with how you would reach each one.","success":"20 named prospects you can contact","time":"2–3 days"},{"id":27,"stage":4,"type":"S","label":"Early adopter signals","short":"Do you know what makes one customer likelier to adopt than another?","text":"What would make one customer substantially more likely to adopt your solution than another?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"c","text":"One or two signals from conversations","points":2},{"id":"e","text":"Signals that predicted who said yes","points":3}],"basis":"Blank, The Four Steps to the Epiphany: earlyvangelist ladder (has the problem, knows it, is looking, has a stopgap, has budget)"},{"id":28,"stage":5,"type":"S","label":"Customer conversations","short":"How many people with this problem have you spoken to?","text":"Have you spoken directly with people who experience this problem?","why":"Patterns only become reliable after about 15 conversations.","quick":true,"weight":2,"gateMin":3,"gateText":"At least 15 conversations","action":"Speak to at least 15 people who have the problem","options":[{"id":"a","text":"None yet","tag":"U","points":0,"skips":[29,30,31,32,33,34,35,36]},{"id":"b","text":"1 to 5 people","points":1},{"id":"c","text":"6 to 14 people","points":2},{"id":"d","text":"15 or more people","points":3}],"basis":"Guest, Bunce & Johnson (2006), Field Methods: themes saturate after about a dozen interviews","howTo":"Run problem interviews until you have spoken to 15 people. Ask about past behaviour and costs, never about your idea (The Mom Test).","success":"15 or more conversations","time":"2–3 weeks"},{"id":29,"stage":5,"type":"S","label":"Recent occasions","short":"Could they describe a recent, specific time it happened?","text":"Can they describe a recent, specific occasion when it occurred?","quick":true,"weight":2,"gateMin":2,"gateText":"Half or more describe a recent occasion","action":"Confirm that half or more can describe a recent occasion","options":[{"id":"a","text":"Not asked yet","tag":"U","points":0},{"id":"b","text":"Few or none could","tag":"N","points":0},{"id":"c","text":"Some could, under half","points":1},{"id":"d","text":"Half or more could","points":2},{"id":"e","text":"Nearly all could","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money; ask about specific past events, not opinions","howTo":"In every interview ask \"Tell me about the last time this happened\" and note who can answer with specifics.","success":"Half or more describe a recent occasion","time":"During your interviews"},{"id":30,"stage":5,"type":"S","label":"Action taken","short":"What did they do about it?","text":"What did they do to address it?","quick":false,"weight":1,"options":[{"id":"a","text":"Didn't ask","tag":"U","points":0},{"id":"b","text":"Nothing","tag":"N","points":0},{"id":"c","text":"Complained or searched, but did not act","points":1},{"id":"d","text":"Built a workaround","points":2},{"id":"e","text":"Paid for a fix","points":3}],"basis":"Blank, The Four Steps to the Epiphany: earlyvangelist ladder (has the problem, knows it, is looking, has a stopgap, has budget)"},{"id":31,"stage":5,"type":"S","label":"Solutions tried","short":"Have they tried existing solutions?","text":"What existing solutions have they tried?","quick":false,"weight":1,"options":[{"id":"a","text":"Didn't ask","tag":"U","points":0},{"id":"b","text":"None had tried anything","tag":"N","points":0},{"id":"f","text":"Fewer than a quarter had","points":1},{"id":"g","text":"A quarter to half had","points":2},{"id":"h","text":"More than half had, and found them lacking","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":32,"stage":5,"type":"S","label":"Money or effort already spent","short":"Have they spent money, time or changed behaviour to solve it?","text":"Have they spent money, invested significant time or changed their behaviour to solve it?","quick":false,"weight":1,"options":[{"id":"a","text":"Not asked yet","tag":"U","points":0},{"id":"b","text":"No","tag":"N","points":0},{"id":"c","text":"One or two have","points":1},{"id":"d","text":"A few have","points":2},{"id":"e","text":"Most have","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money"},{"id":33,"stage":5,"type":"S","label":"Dislikes about current options","short":"Can they say what they dislike about their current options?","text":"What do they dislike about their current options?","quick":false,"weight":1,"options":[{"id":"a","text":"Didn't ask","tag":"U","points":0},{"id":"b","text":"They're mostly satisfied","tag":"N","points":0},{"id":"c","text":"Vague complaints","points":1},{"id":"f","text":"Specific complaints from a few people","points":2},{"id":"g","text":"The same specific complaint from most people","points":3}]},{"id":34,"stage":5,"type":"S","label":"Priority of the problem","short":"Where does this problem rank among their priorities?","text":"How important is this problem compared with their other priorities?","quick":false,"weight":1,"options":[{"id":"a","text":"Didn't ask","tag":"U","points":0},{"id":"f","text":"Not in their top ten","tag":"N","points":0},{"id":"g","text":"In their top ten","points":1},{"id":"h","text":"In their top five","points":2},{"id":"i","text":"In their top three","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":35,"stage":5,"type":"S","label":"Contradicting evidence","short":"Have you looked for evidence that contradicts your assumptions?","text":"What evidence contradicts your original assumptions?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Yes, and it largely contradicts them","tag":"N","points":0},{"id":"c","text":"Looked casually","points":1},{"id":"f","text":"Tested them; some assumptions changed","points":2},{"id":"g","text":"Tested on purpose; the core assumption held","points":3}],"basis":"Camuffo et al. (2020), Management Science: state hypotheses and test them"},{"id":36,"stage":5,"type":"S","label":"Consistent patterns","short":"Do your conversations show a consistent pattern, sceptics included?","text":"Have you spoken to enough people to identify consistent patterns, including people who are sceptical or uninterested?","quick":false,"weight":1,"options":[{"id":"a","text":"Too few to tell","tag":"U","points":0},{"id":"b","text":"No, views are scattered","tag":"N","points":0},{"id":"c","text":"A weak pattern","points":1},{"id":"d","text":"A pattern, but only from supporters","points":2},{"id":"e","text":"A clear pattern, sceptics included","points":3}],"basis":"Guest, Bunce & Johnson (2006), Field Methods: themes saturate after about a dozen interviews"},{"id":37,"stage":6,"type":"C","label":"Current solutions","short":"What do people mostly use today?","text":"What solutions are people using today, including manual workarounds and doing nothing?","options":[{"id":"a","text":"Nothing: they live with it"},{"id":"b","text":"A manual workaround"},{"id":"c","text":"Spreadsheets or general tools"},{"id":"d","text":"An existing product or service"},{"id":"e","text":"Someone they hire"},{"id":"f","text":"A mix of these"}]},{"id":38,"stage":6,"type":"S","label":"Competitors and substitutes","short":"Have you identified the competitors and substitutes?","text":"Which competitors or substitutes address the same underlying need?","quick":false,"weight":1,"options":[{"id":"a","text":"Have not looked","tag":"U","points":0,"skips":[39,40,41]},{"id":"e","text":"Looked briefly online","points":1},{"id":"f","text":"Listed direct and indirect alternatives","points":2},{"id":"g","text":"Compared them using customer feedback","points":3}]},{"id":39,"stage":6,"type":"S","label":"Strengths of alternatives","short":"Do you know what existing solutions do well?","text":"What do existing solutions do well?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"e","text":"From their own marketing","points":1},{"id":"f","text":"From reviews or trying them","points":2},{"id":"g","text":"From customers who use them","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":40,"stage":6,"type":"S","label":"Gaps in alternatives","short":"Do you know where existing solutions fall short?","text":"Where do they fall short?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"They don't fall short","tag":"N","points":0},{"id":"c","text":"My own view","tag":"U","points":0},{"id":"d","text":"A few customers told me","points":2},{"id":"f","text":"Most customers I spoke to said so","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":41,"stage":6,"type":"S","label":"Why the gap persists","short":"Do you know why existing solutions haven't solved it?","text":"Why have existing solutions not fully addressed the problem?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"e","text":"A plausible reason from research","points":2},{"id":"f","text":"A reason confirmed by customers or insiders","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":42,"stage":6,"type":"S","label":"Meaningful gap","short":"Is the gap big enough that customers would seek an alternative?","text":"Is the gap meaningful enough that customers would actively seek an alternative?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know yet","tag":"U","points":0},{"id":"b","text":"No, they'd stay put","tag":"N","points":0},{"id":"c","text":"Maybe: not checked with customers","tag":"U","points":0},{"id":"f","text":"Customers say they'd consider switching","points":2},{"id":"e","text":"Some are already looking for an alternative","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money"},{"id":43,"stage":6,"type":"S","label":"Switching cost","short":"What would it cost a customer to switch?","text":"What would it cost a customer, in money, time and disruption, to switch from what they use today?","quick":false,"weight":1,"options":[{"id":"a","text":"Not assessed","tag":"U","points":0},{"id":"b","text":"Too much to justify","tag":"N","points":0},{"id":"f","text":"High: weeks of effort, or a contract to exit","points":1},{"id":"g","text":"Moderate: a few days of effort","points":2},{"id":"h","text":"Low: hours, with no penalty","points":3}],"basis":"Helmer, 7 Powers (2016): scale, network, counter-positioning, switching costs, brand, cornered resource, process (switching costs)"},{"id":44,"stage":6,"type":"S","label":"Simpler or cheaper alternative","short":"Could they solve it well enough with something simpler or cheaper?","text":"Could a customer solve the problem adequately with a simpler or cheaper solution?","quick":false,"weight":1,"options":[{"id":"a","text":"Not checked","tag":"U","points":0},{"id":"b","text":"Yes, easily","tag":"N","points":0},{"id":"c","text":"Partly","points":1},{"id":"d","text":"Not really","points":2},{"id":"e","text":"No","points":3}]},{"id":45,"stage":6,"type":"S","label":"Point of difference","short":"What would make your approach meaningfully different?","text":"What would make your proposed approach meaningfully different?","quick":false,"weight":1,"options":[{"id":"a","text":"Not defined","tag":"U","points":0},{"id":"b","text":"Nothing significant","tag":"N","points":0},{"id":"c","text":"A feature","points":1},{"id":"d","text":"A different approach","points":2},{"id":"f","text":"A difference customers asked for unprompted","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money"},{"id":46,"stage":6,"type":"S","label":"Difference matters to customers","short":"Do customers say your difference would change their decision?","text":"What evidence suggests that this difference would influence a customer's decision?","quick":true,"weight":2,"gateMin":2,"gateText":"Customers say the difference matters","action":"Hear from customers that your difference would change their decision","options":[{"id":"a","text":"None yet","tag":"U","points":0},{"id":"b","text":"No, they say it doesn't matter","tag":"N","points":0},{"id":"c","text":"My own reasoning","tag":"U","points":0},{"id":"d","text":"Some customers say it would change their choice","points":2},{"id":"f","text":"Customers chose or paid because of it","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)","howTo":"Show five customers your point of difference next to what they use now, then ask for a concrete next step.","success":"Customers say it would change their choice, or act on it","time":"1 week"},{"id":47,"stage":6,"type":"S","label":"Competitor response","short":"Have you thought through how competitors would respond?","text":"How are established competitors likely to respond if you gain traction?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"They could easily shut it out","tag":"N","points":0},{"id":"f","text":"Briefly considered","points":1},{"id":"d","text":"Yes, with a plan","points":2},{"id":"g","text":"Yes; responding would hurt their own business","points":3}],"basis":"Helmer, 7 Powers (2016): scale, network, counter-positioning, switching costs, brand, cornered resource, process (counter-positioning)"},{"id":48,"stage":7,"type":"S","label":"What changed","short":"What has changed that makes this viable now?","text":"What has changed in technology, regulation, cost or customer behaviour that makes this viable now?","quick":true,"weight":2,"gateMin":2,"gateText":"A specific change is identified","action":"Name the specific change that makes this viable now","options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Nothing has changed","tag":"N","points":0},{"id":"c","text":"A general trend","points":1},{"id":"d","text":"A specific change","points":2},{"id":"f","text":"A specific change that is already changing behaviour","points":3}],"howTo":"Name the specific change in technology, regulation, cost or behaviour that makes this possible now, with a date and a source.","success":"A named, dated change with a source","time":"2–3 hours"},{"id":49,"stage":7,"type":"S","label":"Earlier attempts","short":"Has this been tried before, and do you know why it fell short?","text":"Has this been tried before, and why did it fail or stall?","quick":false,"weight":1,"options":[{"id":"a","text":"Haven't checked","tag":"U","points":0},{"id":"b","text":"Yes, and the reasons still apply","tag":"N","points":0},{"id":"c","text":"Tried; not sure why it failed","points":1},{"id":"d","text":"Not tried, as far as I can tell","points":2},{"id":"e","text":"Tried; what's changed fixes why it failed","points":3}]},{"id":50,"stage":7,"type":"S","label":"Window of opportunity","short":"Is the window for this opportunity opening or closing?","text":"Is the window for this opportunity opening or closing, and how long is it likely to stay open?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Closing","tag":"N","points":0},{"id":"c","text":"Hard to say","points":1},{"id":"d","text":"Stable","points":2},{"id":"e","text":"Opening, with signs of new demand","points":3}]},{"id":51,"stage":8,"type":"T","label":"Simplest solution","short":"What is the simplest solution that could solve the problem?","text":"What is the simplest possible solution that could address the problem?","placeholder":"e.g. A text list of on-call clients, sent by hand when a slot opens."},{"id":52,"stage":8,"type":"T","label":"Customer outcome","short":"What outcome should the customer achieve?","text":"What is the primary outcome the customer should achieve?","placeholder":"e.g. Fill 80% of cancelled slots within two hours."},{"id":53,"stage":8,"type":"S","label":"Minimum scope","short":"Have you defined the minimum needed to deliver that outcome?","text":"What is the minimum functionality or service required to deliver that outcome?","quick":false,"weight":1,"options":[{"id":"a","text":"Not defined","tag":"U","points":0,"skips":[54]},{"id":"b","text":"Roughly","points":1},{"id":"e","text":"Written down","points":2},{"id":"f","text":"Written down and tested with customers","points":3}]},{"id":54,"stage":8,"type":"S","label":"What can be removed","short":"Do you know what could be removed without losing value?","text":"What could be removed without significantly reducing the value?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"e","text":"A few ideas","points":1},{"id":"c","text":"Yes, a clear list","points":2},{"id":"d","text":"Yes, confirmed with customers","points":3}]},{"id":55,"stage":8,"type":"S","label":"Riskiest assumption","short":"Have you named the riskiest assumption about the solution?","text":"What is the riskiest assumption about whether the solution will work?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Several, not ranked","points":1},{"id":"e","text":"One named, with a test planned","points":2},{"id":"f","text":"Being tested, with a pass-or-fail threshold","points":3}],"basis":"Camuffo et al. (2020), Management Science: state hypotheses and test them"},{"id":56,"stage":8,"type":"S","label":"Demonstration","short":"What can you show customers?","text":"Can you demonstrate the concept using a sketch, mock-up, prototype, manual service or small pilot?","quick":true,"weight":2,"gateMin":2,"gateText":"A prototype or pilot exists","action":"Show customers a mock-up or prototype","options":[{"id":"a","text":"Nothing to show yet","tag":"U","points":0,"skips":[57]},{"id":"b","text":"A sketch or description","points":1},{"id":"c","text":"A mock-up or prototype","points":2},{"id":"f","text":"A working pilot or manual service used by real customers","points":3}],"basis":"Technology readiness levels (NASA): sketch < prototype < demonstrated in real use","howTo":"Make the cheapest thing customers can react to: a clickable mock-up, a landing page or a manual (concierge) version.","success":"A mock-up or prototype in front of customers","time":"1–2 weeks"},{"id":57,"stage":8,"type":"S","label":"Value understood","short":"Do customers understand the value without much explanation?","text":"Can potential customers understand the proposed value without extensive explanation?","quick":true,"weight":2,"gateMin":2,"gateText":"Customers grasp the value with little explanation","action":"Show that customers grasp the value with little explanation","options":[{"id":"a","text":"Not shown yet","tag":"U","points":0},{"id":"b","text":"Most were confused","tag":"N","points":0},{"id":"c","text":"Only with a lot of explanation","points":1},{"id":"d","text":"With a little explanation","points":2},{"id":"e","text":"Without explanation, and say what it replaces","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money","howTo":"Show it to five customers without explaining it. Ask them to describe what it does and what it would replace.","success":"Most explain the value in their own words","time":"1 week"},{"id":58,"stage":8,"type":"S","label":"Proof it works better","short":"Do you have evidence it works better than the current alternative?","text":"What evidence would demonstrate that the solution works better than the current alternative?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"It works worse","tag":"N","points":0},{"id":"c","text":"My own testing","points":1},{"id":"f","text":"Feedback from customers who tried it","points":2},{"id":"g","text":"Measured results against the current alternative","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":59,"stage":8,"type":"S","label":"Rejection risks","short":"Do you know what would make customers reject it?","text":"What would cause customers to reject it, even if the problem is real?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"Yes, a common deal-breaker","tag":"N","points":0},{"id":"c","text":"My assumption only","tag":"U","points":0},{"id":"d","text":"Reasons customers gave me","points":2},{"id":"f","text":"Known, and addressed in the design","points":3}],"basis":"Framework evidence rule (opinion < observation < commitment)"},{"id":60,"stage":9,"type":"S","label":"Current spending","short":"Are customers already spending money or resources on this?","text":"How are potential customers currently spending money or resources to address this problem?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"No, nothing","tag":"N","points":0},{"id":"f","text":"Time only","points":1},{"id":"g","text":"Time and some money","points":2},{"id":"e","text":"Yes, a set budget for it","points":3}],"basis":"Blank, The Four Steps to the Epiphany: earlyvangelist ladder (has the problem, knows it, is looking, has a stopgap, has budget)"},{"id":61,"stage":9,"type":"S","label":"Budget owner","short":"Do you know who controls the budget?","text":"Who controls the budget for solving it?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"c","text":"Yes, by role","points":2},{"id":"e","text":"Yes, by name, and I've spoken to them","points":3}]},{"id":62,"stage":9,"type":"S","label":"Measurable benefit","short":"Can you measure the benefit your solution would provide?","text":"What measurable financial, operational or personal benefit would your solution provide?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Little measurable benefit","tag":"N","points":0},{"id":"c","text":"A rough estimate","points":1},{"id":"f","text":"Estimated with customers' own numbers","points":2},{"id":"e","text":"Measured in a pilot","points":3}]},{"id":63,"stage":9,"type":"S","label":"Price relative to value","short":"Do you know what customers would pay relative to the value?","text":"How much might a customer reasonably pay relative to the value received?","quick":false,"weight":1,"options":[{"id":"a","text":"Not tested","tag":"U","points":0},{"id":"b","text":"My assumption only","tag":"U","points":0},{"id":"e","text":"A price range from pricing questions with customers","points":2},{"id":"f","text":"A price customers have paid or signed for","points":3}],"basis":"Price research practice (e.g. Van Westendorp): stated price ranges are weaker than prices actually paid"},{"id":64,"stage":9,"type":"C","label":"Pricing model","short":"Which pricing model fits best?","text":"What pricing model would make sense for the customer and the nature of the problem?","options":[{"id":"a","text":"Subscription"},{"id":"b","text":"Per use or transaction"},{"id":"c","text":"One-off purchase"},{"id":"d","text":"Project or retainer fee"},{"id":"e","text":"Outcome or success fee"},{"id":"f","text":"Free with paid upgrades"},{"id":"g","text":"Not decided"}]},{"id":65,"stage":9,"type":"S","label":"Purchase barriers","short":"Do you know what would stop a customer from buying?","text":"What would prevent a customer from purchasing or adopting the solution?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Yes, and it's hard to overcome","tag":"N","points":0},{"id":"c","text":"My assumption only","tag":"U","points":0},{"id":"f","text":"Identified with customers","points":2},{"id":"g","text":"Identified with customers and addressed","points":3}]},{"id":66,"stage":9,"type":"S","label":"Signed or paid commitments","short":"How many customers have made a real commitment: a paid pilot, deposit, purchase order or signed agreement?","text":"What evidence can you obtain of genuine commitment, such as a paid pilot, deposit, purchase order or signed agreement?","why":"A paid pilot, deposit, purchase order or signed agreement counts. Praise does not.","quick":true,"weight":2,"gateMin":3,"gateText":"Three or more signed or paid commitments","action":"Secure three or more signed or paid commitments","options":[{"id":"a","text":"None asked yet","tag":"U","points":0,"skips":[67]},{"id":"b","text":"Asked; nobody committed","tag":"N","points":0},{"id":"c","text":"Verbal interest only, no commitment","points":0,"tag":"U"},{"id":"d","text":"One or two","points":2},{"id":"e","text":"Three or more","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money","howTo":"Ask your most engaged prospects for a paid pilot, deposit, pre-order or signed letter of intent with a price on it.","success":"Three or more signed or paid commitments","time":"2–4 weeks"},{"id":67,"stage":9,"type":"S","label":"Commitment before building","short":"Can you secure commitment before building the full product?","text":"Can you secure that commitment before investing in a fully developed product, where practical?","quick":false,"weight":1,"options":[{"id":"a","text":"Not tried","tag":"U","points":0},{"id":"b","text":"No, they won't commit first","tag":"N","points":0},{"id":"c","text":"Maybe: not tried","tag":"U","points":0},{"id":"f","text":"Yes: pre-orders or letters of intent","points":2},{"id":"g","text":"Yes: paid before it's built","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money"},{"id":68,"stage":9,"type":"S","label":"Praise without action","short":"When people praise the idea, how many take a real next step?","text":"What would you learn if customers praised the idea but refused to take a meaningful next step?","quick":false,"weight":1,"options":[{"id":"a","text":"Haven't tested","tag":"U","points":0},{"id":"f","text":"Fewer than 1 in 10","tag":"N","points":0},{"id":"g","text":"1 to 2 in 10","points":1},{"id":"h","text":"3 to 5 in 10","points":2},{"id":"i","text":"More than half","points":3}],"basis":"Fitzpatrick, The Mom Test (2013): commitment is paid in time, reputation or money; Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":69,"stage":10,"type":"S","label":"Pilot outcomes","short":"Did your first customers get the promised outcome?","text":"Did your first customers achieve the outcome you promised, and how do you know?","quick":true,"weight":2,"gateMin":2,"gateText":"Most pilot customers achieved the outcome","action":"Run a pilot in which most customers achieve the promised outcome","options":[{"id":"a","text":"No pilot yet","tag":"U","points":0,"skips":[70]},{"id":"f","text":"Few or none did","tag":"N","points":0},{"id":"g","text":"Under half did","points":1},{"id":"h","text":"More than half did","points":2},{"id":"e","text":"All did, with measured results","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers","howTo":"Run a small pilot with success criteria agreed up front, and measure the outcome you promised.","success":"More than half reach the promised outcome","time":"4–8 weeks"},{"id":70,"stage":10,"type":"S","label":"Renewals and referrals","short":"Did any renew, buy again, expand or refer someone?","text":"Did they renew, buy again, expand their use or refer someone else?","quick":true,"weight":2,"gateMin":2,"gateText":"At least one renewed or referred","action":"Get at least one pilot customer to renew, buy again or refer someone","options":[{"id":"a","text":"Too early to tell","tag":"U","points":0},{"id":"b","text":"None did","tag":"N","points":0},{"id":"c","text":"One did","points":2},{"id":"d","text":"Several did","points":3}],"basis":"Sean Ellis product-market fit test: 40%+ 'very disappointed' without the product","howTo":"At the end of the pilot, ask each customer to renew, buy again, expand or introduce you to a peer.","success":"At least one renews, buys again or refers","time":"2 weeks after the pilot"},{"id":71,"stage":11,"type":"S","label":"First ten customers","short":"Can you name your first ten customers and how you'll reach each?","text":"Can you name your first ten customers and say how you will get in front of each one?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"e","text":"Fewer than 5 named","points":1},{"id":"f","text":"5 to 9 named","points":2},{"id":"d","text":"All ten, with a route to each","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":72,"stage":11,"type":"S","label":"Channel test","short":"What did a small test of your main channel show?","text":"Have you run a small test of your main channel, and what did it cost per qualified conversation?","quick":true,"weight":2,"gateMin":3,"gateText":"A channel test at a cost the model supports","action":"Test your main channel at a cost the model can support","options":[{"id":"a","text":"No test yet","tag":"U","points":0},{"id":"b","text":"Little response, or too costly","tag":"N","points":0},{"id":"c","text":"A few qualified conversations","points":1},{"id":"d","text":"Promising, cost not yet clear","points":2},{"id":"e","text":"Qualified conversations at a cost the model supports","points":3}],"basis":"Skok, SaaS Metrics 2.0: customer value at least 3x acquisition cost; recover it within 12 months","howTo":"Spend a small, fixed budget on your main channel. Count qualified conversations and the cost of each.","success":"Qualified conversations at a cost your model supports (customer value at least 3x acquisition cost)","time":"2–4 weeks"},{"id":73,"stage":11,"type":"S","label":"Repeatable channel","short":"Does that channel work beyond your personal network?","text":"Is that channel repeatable, or does it depend on your personal network?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know yet","tag":"U","points":0},{"id":"b","text":"No, it's only my own network","tag":"N","points":0},{"id":"c","text":"Partly","points":1},{"id":"f","text":"Some results came from strangers","points":2},{"id":"g","text":"Most results came from strangers","points":3}]},{"id":74,"stage":12,"type":"S","label":"Number with the problem","short":"Do you know how many potential customers have this problem?","text":"How many potential customers experience this problem?","quick":false,"weight":1,"options":[{"id":"a","text":"Not estimated","tag":"U","points":0},{"id":"b","text":"A rough guess","tag":"U","points":0},{"id":"e","text":"Top-down, from industry reports","points":2},{"id":"f","text":"Bottom-up, counted from real data","points":3}]},{"id":75,"stage":12,"type":"S","label":"Reachable market","short":"Could the customers you can realistically serve meet your Stage 2 goals?","text":"How many of those customers could realistically be served by your business?","quick":true,"weight":2,"gateMin":2,"gateText":"Enough customers at a moderate share or less","action":"Show that a moderate share of the reachable market meets your Stage 2 goals","options":[{"id":"a","text":"Not estimated","tag":"U","points":0},{"id":"b","text":"Too few customers to meet the goals set in Stage 2","tag":"N","points":0,"knockout":"abandon"},{"id":"c","text":"Enough only with a large share","points":1},{"id":"d","text":"Enough at a moderate share","points":2},{"id":"e","text":"Enough at a small share","points":3}],"howTo":"Count reachable customers bottom-up, multiply by a realistic price and a 5–10% share, and compare with your Stage 2 goal.","success":"Your goal is met at a moderate share or less","time":"2–3 days"},{"id":76,"stage":12,"type":"S","label":"Current spend on solutions","short":"Do you know what they spend on existing solutions?","text":"How much are they currently spending on existing solutions?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Very little","tag":"N","points":0},{"id":"c","text":"A rough guess","tag":"U","points":0},{"id":"f","text":"An estimate from customers","points":2},{"id":"g","text":"Known, from budgets, receipts or data","points":3}]},{"id":77,"stage":12,"type":"S","label":"Market direction","short":"How fast is the market growing?","text":"Is the market growing, stable or declining?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"f","text":"Shrinking","tag":"N","points":0},{"id":"g","text":"Flat, or mixed signals","points":1},{"id":"h","text":"Growing up to 10% a year","points":2},{"id":"i","text":"Growing over 10% a year, per published data","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":78,"stage":12,"type":"S","label":"Starting segment","short":"Have you chosen the best segment to start with?","text":"What geographic, industry or customer segment would be the best starting point?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Several options","points":1},{"id":"c","text":"Chosen","points":2},{"id":"e","text":"Chosen, with evidence it's the easiest to reach","points":3}]},{"id":79,"stage":12,"type":"C","label":"Main sales channel","short":"How will you mainly reach customers?","text":"How will you reach potential customers?","options":[{"id":"a","text":"Direct sales"},{"id":"b","text":"Referrals and word of mouth"},{"id":"c","text":"Content and search"},{"id":"d","text":"Paid advertising"},{"id":"e","text":"Partners or resellers"},{"id":"f","text":"Marketplaces or app stores"},{"id":"g","text":"Events and communities"},{"id":"h","text":"Not decided"}]},{"id":80,"stage":12,"type":"S","label":"Acquisition cost","short":"Do you know what it costs to acquire a customer?","text":"What would it cost, in money and time, to acquire a customer?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"More than a customer is worth","tag":"N","points":0},{"id":"c","text":"A guess","tag":"U","points":0},{"id":"f","text":"Estimated from a small test","points":2},{"id":"g","text":"Measured over several sales","points":3}],"basis":"Skok, SaaS Metrics 2.0: customer value at least 3x acquisition cost; recover it within 12 months"},{"id":81,"stage":12,"type":"S","label":"Sales cycle","short":"How long does it take to turn a prospect into a paying customer?","text":"How long might it take to convert a prospect into a paying customer?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Over a year","tag":"N","points":0},{"id":"c","text":"6 to 12 months","points":1},{"id":"d","text":"1 to 6 months","points":2},{"id":"e","text":"Under a month","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":82,"stage":12,"type":"S","label":"Path to a larger market","short":"Is there a credible path from your niche to a larger market?","text":"Is there a credible path from an initial niche to a larger market?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"No, it stays a niche","tag":"N","points":0},{"id":"c","text":"Possibly: not checked","points":0,"tag":"U"},{"id":"d","text":"Yes, a likely path","points":2},{"id":"e","text":"Yes, with adjacent demand already seen","points":3}]},{"id":83,"stage":13,"type":"S","label":"Revenue model","short":"Is it clear exactly how the business will make money?","text":"How exactly will the business generate revenue?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Roughly","points":1},{"id":"c","text":"Yes","points":2},{"id":"d","text":"Yes, and customers have paid this way","points":3}]},{"id":84,"stage":13,"type":"C","label":"What customers pay for","short":"What will customers pay for?","text":"What will the customer pay for: access, usage, transactions, outcomes, products or services?","options":[{"id":"a","text":"Access"},{"id":"b","text":"Usage"},{"id":"c","text":"Transactions"},{"id":"d","text":"Outcomes"},{"id":"e","text":"Products"},{"id":"f","text":"Services"},{"id":"g","text":"A mix"}]},{"id":85,"stage":13,"type":"S","label":"Cost to deliver","short":"Do you know what it costs to create, deliver and support?","text":"What will it cost to create, deliver and support the offering?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0,"skips":[86,94]},{"id":"b","text":"A rough guess","points":0,"tag":"U"},{"id":"c","text":"An estimate","points":2},{"id":"d","text":"Known from a pilot","points":3}]},{"id":86,"stage":13,"type":"S","label":"Margin","short":"What gross margin could you realistically achieve?","text":"What gross margin and contribution margin could realistically be achieved?","why":"Generic bands; adjust per sector in the question bank.","quick":false,"weight":1,"options":[{"id":"a","text":"Not worked out","tag":"U","points":0},{"id":"b","text":"Below 20%","tag":"N","points":0},{"id":"c","text":"20% to 40%","points":1},{"id":"d","text":"40% to 60%","points":2},{"id":"e","text":"Above 60%","points":3}]},{"id":87,"stage":13,"type":"S","label":"Upfront investment","short":"Do you know the upfront investment to reach the first paying customer?","text":"What upfront investment is required to reach the first paying customer?","quick":false,"weight":1,"options":[{"id":"a","text":"Not worked out","tag":"U","points":0},{"id":"b","text":"More than I can raise","tag":"N","points":0},{"id":"c","text":"A rough guess","points":0,"tag":"U"},{"id":"d","text":"Estimated and affordable","points":2},{"id":"e","text":"Small and already covered","points":3}]},{"id":88,"stage":13,"type":"S","label":"Working capital","short":"Do you know how much working capital the business needs?","text":"How much working capital will the business need?","quick":false,"weight":1,"options":[{"id":"a","text":"Not worked out","tag":"U","points":0},{"id":"b","text":"More than is available","tag":"N","points":0},{"id":"c","text":"A rough guess","points":0,"tag":"U"},{"id":"d","text":"Estimated","points":2},{"id":"e","text":"Estimated and covered","points":3}]},{"id":89,"stage":13,"type":"S","label":"Funding source","short":"How will you fund the business until it covers its costs?","text":"How will you fund the business until it covers its own costs: savings, customer revenue, debt, grants or investors?","quick":true,"weight":2,"gateMin":1,"gateText":"A funding source is identified","action":"Identify a realistic source of funding","options":[{"id":"a","text":"Not worked out","tag":"U","points":0,"skips":[90]},{"id":"b","text":"No realistic source of funding","tag":"N","points":0,"knockout":"abandon"},{"id":"c","text":"A source identified, not yet confirmed","points":1},{"id":"d","text":"A source confirmed in principle","points":2},{"id":"e","text":"Secured, or customer revenue covers it","points":3}],"howTo":"List your funding options (savings, revenue, loans, grants, investors) and the next step for each.","success":"One realistic funding source identified","time":"1 week"},{"id":90,"stage":13,"type":"S","label":"Funder fit","short":"Does that funding source expect what your Stage 2 goals offer?","text":"Does the business you described in Stage 2 match what that funding source expects in return?","quick":false,"weight":1,"options":[{"id":"a","text":"Not checked","tag":"U","points":0},{"id":"b","text":"No, they expect something different","tag":"N","points":0},{"id":"c","text":"Unsure: not checked","points":0,"tag":"U"},{"id":"d","text":"Mostly","points":2},{"id":"e","text":"Yes","points":3}]},{"id":91,"stage":13,"type":"S","label":"Purchase frequency","short":"How often will customers buy, renew or generate revenue?","text":"How frequently will customers purchase, renew or generate revenue?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Once, rarely again","tag":"N","points":0},{"id":"c","text":"Occasionally","points":1},{"id":"d","text":"Several times a year","points":2},{"id":"e","text":"Monthly or continuously","points":3}]},{"id":92,"stage":13,"type":"S","label":"Customer value vs acquisition cost","short":"What is a customer worth compared with what they cost to acquire?","text":"What is a customer worth over their lifetime compared with what they cost to acquire?","quick":true,"weight":2,"gateMin":3,"gateText":"A customer is worth three times acquisition cost","action":"Show that a customer is worth at least three times what they cost to acquire","options":[{"id":"a","text":"Don't know","tag":"U","points":0,"skips":[93]},{"id":"b","text":"Less than they cost","tag":"N","points":0},{"id":"c","text":"1 to 2 times the cost","points":1},{"id":"d","text":"2 to 3 times the cost","points":2},{"id":"e","text":"3 times or more","points":3}],"basis":"Skok, SaaS Metrics 2.0: customer value at least 3x acquisition cost; recover it within 12 months","howTo":"Estimate what a customer is worth (price x gross margin x expected lifetime) and divide by your measured acquisition cost.","success":"Customer value at least 3x acquisition cost","time":"1 day, once you have channel data"},{"id":93,"stage":13,"type":"S","label":"Payback period","short":"How long to recover the cost of acquiring a customer?","text":"How long does it take to recover the cost of acquiring a customer?","why":"Generic bands; adjust per sector in the question bank.","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"Over 2 years","tag":"N","points":0},{"id":"c","text":"12 to 24 months","points":1},{"id":"d","text":"6 to 12 months","points":2},{"id":"e","text":"Under 6 months","points":3}],"basis":"Skok, SaaS Metrics 2.0: customer value at least 3x acquisition cost; recover it within 12 months"},{"id":94,"stage":13,"type":"S","label":"Break-even","short":"Do you know what the business must earn to cover its costs?","text":"What would the business need to earn to cover its operating costs?","quick":false,"weight":1,"options":[{"id":"a","text":"Not worked out","tag":"U","points":0},{"id":"b","text":"A rough guess","points":0,"tag":"U"},{"id":"c","text":"Estimated","points":2},{"id":"d","text":"Calculated and within reach","points":3}]},{"id":95,"stage":13,"type":"S","label":"Sensitivity","short":"Would the business survive a 20% miss on price, cost or demand?","text":"How sensitive is profitability to lower prices, higher costs or weaker demand?","quick":true,"weight":2,"gateMin":2,"gateText":"Survives a 20% miss on one input","action":"Show the business survives a 20% miss on price, cost or demand","options":[{"id":"a","text":"Not tested","tag":"U","points":0},{"id":"b","text":"No, it would lose money","tag":"N","points":0},{"id":"c","text":"Only just","points":1},{"id":"d","text":"Yes, on any one of them","points":2},{"id":"e","text":"Yes, even on two at once","points":3}],"basis":"Camuffo et al. (2020), Management Science: state hypotheses and test them","howTo":"In a simple spreadsheet, cut price, raise cost and cut demand by 20%, one at a time.","success":"The business still covers its costs in each case","time":"Half a day"},{"id":96,"stage":13,"type":"S","label":"Realistic growth","short":"Is it viable without unrealistic growth or constant outside funding?","text":"Can the business remain viable without relying on unrealistic growth assumptions or continuous outside funding?","quick":false,"weight":1,"options":[{"id":"a","text":"Not assessed","tag":"U","points":0},{"id":"b","text":"No","tag":"N","points":0},{"id":"c","text":"Only with strong growth","points":1},{"id":"d","text":"Yes, with modest growth","points":2},{"id":"e","text":"Yes, even with flat growth","points":3}]},{"id":97,"stage":14,"type":"S","label":"Skills required","short":"Have you listed the skills and experience needed?","text":"What skills, experience and industry knowledge are required?","quick":false,"weight":1,"options":[{"id":"a","text":"Not listed","tag":"U","points":0,"skips":[98,99]},{"id":"b","text":"Partly","points":1},{"id":"c","text":"Yes","points":2},{"id":"d","text":"Yes, checked with people in the industry","points":3}]},{"id":98,"stage":14,"type":"S","label":"Capabilities you have","short":"What share of those capabilities do you already have?","text":"Which of these capabilities do you already possess?","quick":false,"weight":1,"options":[{"id":"a","text":"Not assessed","tag":"U","points":0},{"id":"f","text":"Under a quarter","tag":"N","points":0},{"id":"g","text":"A quarter to half","points":1},{"id":"h","text":"Half to three quarters","points":2},{"id":"i","text":"More than three quarters","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":99,"stage":14,"type":"S","label":"Filling the gaps","short":"Do you know how to fill the missing expertise, partners or suppliers?","text":"What expertise, partners, employees or suppliers are missing?","quick":false,"weight":1,"options":[{"id":"a","text":"Not assessed","tag":"U","points":0},{"id":"b","text":"No way to fill them","tag":"N","points":0},{"id":"c","text":"Some ideas","points":1},{"id":"d","text":"Yes, a plan","points":2},{"id":"e","text":"Already covered","points":3}]},{"id":100,"stage":14,"type":"S","label":"Founder agreement","short":"If there are co-founders, have you agreed roles, ownership and exits?","text":"If there is more than one founder, have you agreed on roles, ownership, decision rights and what happens if one of you leaves?","quick":false,"weight":1,"options":[{"id":"a","text":"Not discussed","tag":"U","points":0},{"id":"b","text":"I am the only founder","tag":"X","points":0},{"id":"c","text":"We disagree","tag":"N","points":0},{"id":"d","text":"Discussed informally","points":1},{"id":"e","text":"Agreed verbally","points":2},{"id":"g","text":"Agreed in writing, including vesting and exits","points":3}],"basis":"Wasserman, The Founder's Dilemmas (2012): co-founder conflict is a leading cause of startup failure"},{"id":101,"stage":14,"type":"S","label":"First version within limits","short":"Can the first version be built within the time and money you set in Stage 2?","text":"What will it take to build and deliver the first version?","quick":true,"weight":2,"gateMin":2,"gateText":"The first version fits the Stage 2 limits","action":"Cost the first version within your Stage 2 time and money limits","options":[{"id":"a","text":"Not estimated","tag":"U","points":0},{"id":"b","text":"No, well beyond my limits","tag":"N","points":0},{"id":"c","text":"Only if things go well","points":1},{"id":"d","text":"Yes, within limits","points":2},{"id":"e","text":"Yes, comfortably","points":3}],"howTo":"List what the first version needs, cost and time each item, and compare the total with your Stage 2 limits.","success":"The first version fits your time and money limits","time":"1–2 days"},{"id":102,"stage":14,"type":"S","label":"Launch barriers","short":"Are there technical, regulatory or legal barriers to launch?","text":"What technical, operational, regulatory or legal barriers could prevent launch?","quick":false,"weight":1,"options":[{"id":"a","text":"Not checked","tag":"U","points":0},{"id":"b","text":"Yes, a serious one","tag":"N","points":0},{"id":"c","text":"Possibly: not checked","points":0,"tag":"U"},{"id":"d","text":"Minor, manageable ones","points":2},{"id":"e","text":"None found after checking","points":3}]},{"id":103,"stage":14,"type":"S","label":"Ownership","short":"Do you own the idea outright?","text":"Do you own the idea outright, or could an employer, co-founder or former partner have a claim to it?","quick":true,"weight":2,"gateMin":2,"gateText":"Ownership is clear","action":"Confirm in writing that you own the idea","options":[{"id":"a","text":"Not checked","tag":"U","points":0},{"id":"b","text":"Someone else has or may have a claim to the idea, unresolved","tag":"N","points":0,"knockout":"stage"},{"id":"c","text":"A possible claim, resolved in writing","points":2},{"id":"d","text":"Yes, nobody else has a claim","points":3}],"howTo":"Check employment contracts, partner agreements and earlier work; get any possible claim released in writing.","success":"Clear ownership, confirmed in writing","time":"1–2 weeks"},{"id":104,"stage":14,"type":"S","label":"Licences and obligations","short":"Do you know what licences, insurance or privacy obligations apply?","text":"What licences, certifications, insurance or data privacy obligations apply?","quick":false,"weight":1,"options":[{"id":"a","text":"Not checked","tag":"U","points":0},{"id":"b","text":"Yes, and they're prohibitive","tag":"N","points":0},{"id":"c","text":"Partly","points":1},{"id":"d","text":"Yes, identified","points":2},{"id":"e","text":"Yes, and covered or none apply","points":3}]},{"id":105,"stage":14,"type":"S","label":"Intellectual property","short":"Could the solution infringe someone else's intellectual property?","text":"Could the solution infringe on anyone else's intellectual property?","quick":true,"weight":1,"options":[{"id":"a","text":"Not checked","tag":"U","points":0},{"id":"b","text":"The solution likely infringes someone else's intellectual property","tag":"N","points":0,"knockout":"stage"},{"id":"c","text":"Possible overlap, unresolved","points":1},{"id":"d","text":"Checked, no conflict found","points":3}],"basis":"A freedom-to-operate search checks existing patents and marks before launch","howTo":"Run a freedom-to-operate search on patents and trademarks, or ask an IP lawyer for a short opinion.","success":"No conflict found, or a clear way around it","time":"1–2 weeks","action":"Check for intellectual-property conflicts"},{"id":106,"stage":14,"type":"S","label":"Time committed","short":"How many hours a week can you realistically commit?","text":"How much time and money can you realistically commit?","quick":false,"weight":1,"options":[{"id":"a","text":"Not decided","tag":"U","points":0},{"id":"f","text":"Under 5 hours","tag":"N","points":0},{"id":"g","text":"5 to 15 hours","points":1},{"id":"h","text":"15 to 30 hours","points":2},{"id":"i","text":"More than 30 hours","points":3}],"basis":"Krosnick & Presser (2010): use natural metrics instead of vague quantifiers"},{"id":107,"stage":14,"type":"S","label":"Smallest experiment","short":"Have you defined the smallest experiment to test the idea?","text":"What is the smallest experiment you can run to learn whether the idea works?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Roughly","points":1},{"id":"c","text":"Yes, defined","points":2},{"id":"e","text":"Running, with a pass-or-fail threshold","points":3}],"basis":"Camuffo et al. (2020), Management Science: state hypotheses and test them"},{"id":108,"stage":14,"type":"S","label":"Do yourself or pay for","short":"Do you know what you'll do yourself and what you'll pay for?","text":"What can you do yourself, and what must you pay someone else to do?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Roughly","points":1},{"id":"c","text":"Yes","points":2},{"id":"d","text":"Yes, and costed","points":3}]},{"id":109,"stage":14,"type":"S","label":"Delivery risks","short":"Have you identified the biggest risks to delivering?","text":"What are the biggest risks that could prevent you from delivering on the promise?","quick":false,"weight":1,"options":[{"id":"a","text":"Not yet","tag":"U","points":0},{"id":"b","text":"Yes, and one looks unmanageable","tag":"N","points":0},{"id":"c","text":"A few, loosely","points":1},{"id":"d","text":"Yes, listed","points":2},{"id":"e","text":"Yes, with a plan for each","points":3}]},{"id":110,"stage":15,"type":"S","label":"Barriers to copying","short":"What would stop competitors copying it?","text":"If the idea succeeds, what would prevent competitors from copying it?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"Nothing; it's easy to copy","tag":"N","points":0},{"id":"f","text":"Only being first or faster","points":1},{"id":"g","text":"One lasting advantage: switching costs, network effects, scale, brand, a scarce resource or a hard-to-copy process","points":2},{"id":"h","text":"Two or more of those","points":3}],"basis":"Helmer, 7 Powers (2016): scale, network, counter-positioning, switching costs, brand, cornered resource, process"},{"id":111,"stage":15,"type":"S","label":"Advantage that builds","short":"Could an advantage build up as you grow, such as network effects, scale, switching costs or brand?","text":"Could the business develop proprietary knowledge, technology, data, brand recognition, distribution advantages or network effects?","quick":true,"weight":2,"gateMin":2,"gateText":"An advantage can build over time","action":"Name one advantage that should strengthen as the business grows","options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"No advantage would build","tag":"N","points":0},{"id":"c","text":"Possibly, nothing specific","points":0,"tag":"U"},{"id":"d","text":"Yes, one specific advantage","points":2},{"id":"e","text":"Yes, and it's already building","points":3}],"basis":"Helmer, 7 Powers (2016): scale, network, counter-positioning, switching costs, brand, cornered resource, process","howTo":"Decide which lasting advantage could apply (network effects, scale, switching costs, brand, a scarce resource or a hard-to-copy process) and what makes it grow.","success":"One named advantage that strengthens as you grow","time":"Half a day"},{"id":112,"stage":15,"type":"S","label":"Reasons to stay","short":"Would customers have strong reasons to keep using it?","text":"Would customers have compelling reasons to continue using the solution over time?","quick":false,"weight":1,"options":[{"id":"a","text":"Don't know","tag":"U","points":0},{"id":"b","text":"No, it's easy to drop","tag":"N","points":0},{"id":"c","text":"Some reasons","points":1},{"id":"f","text":"Users say they'd miss it","points":2},{"id":"g","text":"40% or more say they'd be 'very disappointed' without it","points":3}],"basis":"Sean Ellis product-market fit test: 40%+ 'very disappointed' without the product"},{"id":113,"stage":15,"type":"S","label":"Gains with scale","short":"Would the business get more efficient or valuable as it grows?","text":"Could the business become more efficient or valuable as it grows?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"No, it gets harder","tag":"N","points":0},{"id":"c","text":"Slightly","points":1},{"id":"d","text":"Yes","points":2},{"id":"e","text":"Yes, and it's already measurable","points":3}]},{"id":114,"stage":15,"type":"S","label":"Delivery without you","short":"Can someone other than you deliver it consistently?","text":"Can the offering be delivered consistently by someone other than you?","quick":false,"weight":1,"options":[{"id":"a","text":"Not tested","tag":"U","points":0},{"id":"b","text":"No, it depends on me","tag":"N","points":0},{"id":"c","text":"With difficulty","points":1},{"id":"d","text":"Yes, with training","points":2},{"id":"e","text":"Yes, already done","points":3}]},{"id":115,"stage":15,"type":"S","label":"Obsolescence risk","short":"What could make the offering obsolete?","text":"What could make the offering obsolete or less relevant?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"A threat already visible","tag":"N","points":0},{"id":"c","text":"Some real risks","points":1},{"id":"d","text":"Minor risks","points":2},{"id":"e","text":"Considered: low risk","points":3}]},{"id":116,"stage":15,"type":"S","label":"External threats","short":"Could changes in behaviour, technology, regulation or competition undermine it?","text":"What changes in customer behaviour, technology, regulation or competition could undermine the business?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"Yes, likely soon","tag":"N","points":0},{"id":"c","text":"Yes, possibly","points":1},{"id":"d","text":"Unlikely, with a plan","points":2},{"id":"e","text":"Considered: low risk","points":3}]},{"id":117,"stage":15,"type":"S","label":"Single dependency","short":"Does the business depend on one platform, supplier, partner, customer or rule?","text":"Does the business depend on a single platform, supplier, partner, customer or regulation, and what happens if that changes?","quick":true,"weight":2,"gateMin":2,"gateText":"No single fatal dependency","action":"Find a fallback for any dependency that could end the business","options":[{"id":"a","text":"Not assessed","tag":"U","points":0},{"id":"b","text":"Yes, one that could end the business","tag":"N","points":0},{"id":"c","text":"Yes, but with a fallback","points":2},{"id":"d","text":"No critical dependency","points":3}],"basis":"Customer, supplier and platform concentration risk","howTo":"List every platform, supplier, partner, customer or rule you depend on, and find a fallback for any that could end the business.","success":"No single dependency without a fallback","time":"1–2 days"},{"id":118,"stage":15,"type":"S","label":"Sustaining the advantage","short":"Do you know how to keep the advantage as the market changes?","text":"How could the business maintain its advantage as the market evolves?","quick":false,"weight":1,"options":[{"id":"a","text":"Not considered","tag":"U","points":0},{"id":"b","text":"Loosely","points":1},{"id":"c","text":"Yes, a plan","points":2},{"id":"d","text":"Yes, already in motion","points":3}]},{"id":119,"stage":16,"type":"T","label":"Critical assumptions","short":"What three assumptions must be true for this to succeed?","text":"What are the three most important assumptions that must be true for this business to succeed?","placeholder":"e.g. 1. Groomers lose 2+ bookings a week. 2. Clients will take short-notice slots. 3. Groomers pay $30 a month."},{"id":120,"stage":16,"type":"C","label":"Least-supported assumption","short":"Which of those assumptions has the least evidence?","text":"Which of these assumptions is the least supported by evidence?","options":[{"id":"a","text":"The first"},{"id":"b","text":"The second"},{"id":"c","text":"The third"},{"id":"d","text":"Not sure"}]},{"id":121,"stage":16,"type":"T","label":"Cheapest test","short":"What is the cheapest, fastest experiment to test it?","text":"What is the cheapest, fastest experiment that could test the riskiest assumption?","placeholder":"e.g. Text 10 groomers' client lists by hand for two weeks."},{"id":122,"stage":16,"type":"C","label":"Proof needed to invest","short":"What results would justify investing more?","text":"What measurable results would justify investing more time and money?","options":[{"id":"a","text":"A set number of paying customers"},{"id":"b","text":"A revenue target"},{"id":"c","text":"Usage or retention numbers"},{"id":"d","text":"A successful pilot"},{"id":"e","text":"Not defined yet"}]},{"id":123,"stage":16,"type":"C","label":"Exit criteria","short":"Have you decided what evidence would make you change or abandon it?","text":"What evidence would cause you to change the idea or abandon it?","options":[{"id":"a","text":"Yes, written down with numbers"},{"id":"b","text":"Yes, roughly"},{"id":"c","text":"Not yet"}]},{"id":124,"stage":16,"type":"C","label":"Best use of your time","short":"Is this the best opportunity compared with other uses of your time?","text":"Based on what you have learned, is this the best opportunity to pursue compared with other uses of your time and resources?","options":[{"id":"a","text":"Yes"},{"id":"b","text":"Probably"},{"id":"c","text":"Not sure"},{"id":"d","text":"Probably not"},{"id":"e","text":"No"}]}]};
window.SPARK_REPORT_CSS = "/* ==========================================================\n   OPTIVUS BRAND TOKENS for PRISM - SPARK\n   Read from the live optivusprof.ca stylesheet (:root) on 2026-10-10:\n     --ink #0F172A · --ink-mid #1E2937 · --ocean-blue (emerald) #10B981\n     --dark-blue (deep emerald) #065F46 · --soft-cyan #34D399 · --pale-blue #D1FAE5\n     --off-white #F5F2ED · --rule #E2D9C8 · --muted #94A3B8\n     fonts 'Aptos Display' / 'Aptos', 'Inter', system-ui\n   The site's palette is Tailwind slate + emerald, so the status colours SPARK\n   needs that the site doesn't have (amber, red) come from the same family.\n   Loaded before spark.css; contains only custom properties.\n   ========================================================== */\n:root {\n  /* Brand */\n  --ink: #0F172A;\n  --ink-mid: #1E2937;\n  --emerald: #10B981;\n  --emerald-deep: #065F46;\n  --emerald-soft: #34D399;\n  --emerald-pale: #D1FAE5;\n  --off-white: #F5F2ED;\n  --rule: #E2D9C8;\n  --slate-muted: #94A3B8;\n\n  --font: 'Aptos', 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;\n  --font-display: 'Aptos Display', 'Aptos', 'Inter', system-ui, -apple-system, 'Segoe UI', sans-serif;\n\n  /* Roles used throughout spark.css */\n  --accent: var(--emerald);\n  --accent-strong: var(--emerald-deep);\n  --accent-soft: var(--emerald-pale);\n  --brand-blue: var(--ink);\n  --brand-blue-soft: rgba(15, 23, 42, 0.06);\n\n  --bg-base: #ffffff;\n  --bg-panel: #ffffff;\n  --bg-elevated: var(--off-white);\n\n  --text-primary: var(--ink);\n  /* The site's #94A3B8 is used on its dark bands; on white it is too faint for body text,\n     so secondary text uses the darker slates from the same family. */\n  --text-secondary: #475569;\n  --text-muted: #64748B;\n\n  --status-good: var(--emerald-deep);\n  --status-good-soft: var(--emerald-pale);\n  --status-warn: #92400E;\n  --status-warn-soft: #FEF3C7;\n  --status-danger: #B91C1C;\n  --status-danger-soft: #FEE2E2;\n\n  --shadow-sm: 0 2px 12px rgba(6, 95, 70, 0.08);\n  --shadow-md: 0 8px 32px rgba(6, 95, 70, 0.10);\n}\n\n/* PRISM - SPARK report: a standalone, printable document in the Optivus palette.\n   Uses optivus_tokens.css (inlined into the downloaded file). No web fonts, no external assets. */\n\n* { box-sizing: border-box; }\nhtml, body { margin: 0; padding: 0; }\nbody { font-family: var(--font); color: var(--ink); background: var(--off-white); font-size: 15px; line-height: 1.55;\n  -webkit-font-smoothing: antialiased; font-variant-numeric: tabular-nums; }\nh1, h2, h3 { font-family: var(--font-display); line-height: 1.2; margin: 0; }\np { margin: 0 0 8px; }\n.muted { color: var(--text-muted); }\n.small { font-size: 13px; }\n.nowrap { white-space: nowrap; }\na { color: var(--emerald-deep); }\n\n/* Toolbar (screen only) */\n.toolbar { position: sticky; top: 0; z-index: 5; display: flex; flex-wrap: wrap; gap: 8px 16px; align-items: center;\n  justify-content: space-between; padding: 10px 16px; background: var(--ink); border-bottom: 3px solid var(--emerald); }\n.toolbar > a { color: #E2E8F0; font-weight: 600; text-decoration: none; }\n.toolbar-actions { display: flex; gap: 8px; flex-wrap: wrap; }\n.tb-btn { font: inherit; font-weight: 700; font-size: 14px; padding: 8px 14px; border-radius: 4px; cursor: pointer;\n  border: 1px solid rgba(255,255,255,.25); background: transparent; color: #fff; text-decoration: none; }\n.tb-btn:hover { background: rgba(255,255,255,.1); }\n.tb-primary { background: var(--emerald); border-color: var(--emerald); }\n.tb-primary:hover { background: var(--emerald-deep); }\n\n.report { max-width: 920px; margin: 24px auto 48px; background: #fff; border-radius: 14px; overflow: hidden;\n  box-shadow: var(--shadow-md); }\n\n/* Cover */\n.cover { background: var(--ink); color: #fff; padding: 32px 40px 28px; border-bottom: 4px solid var(--emerald); }\n.cover-brand { font-weight: 800; letter-spacing: .03em; font-size: 14px; color: #fff; margin-bottom: 18px; }\n.cover-mark { color: var(--emerald); }\n.cover-sub { font-weight: 400; color: var(--slate-muted); margin-left: 6px; letter-spacing: 0; }\n.cover-title { font-size: 34px; color: #fff; margin-bottom: 8px; }\n.cover-meta { color: #CBD5E1; font-size: 14px; margin: 0; }\n\n/* Verdict */\n.verdict-panel { display: grid; grid-template-columns: minmax(0, 320px) 1fr; gap: 28px; align-items: center; padding: 28px 40px 8px; }\n.dial-static { width: 100%; height: auto; display: block; }\n.zone-key, .legend { display: flex; flex-wrap: wrap; gap: 4px 14px; justify-content: center; font-size: 12px; color: var(--text-secondary); margin: 6px 0 0; }\n.k-red { color: #DC2626; } .k-yellow { color: #B45309; } .k-green { color: var(--emerald-deep); }\n.rating { display: flex; align-items: baseline; gap: 6px; flex-wrap: wrap; margin: 0; }\n.rating-num { font-family: var(--font-display); font-size: 64px; font-weight: 800; line-height: 1; }\n.rating-of { font-size: 20px; color: var(--text-muted); font-weight: 600; }\n.rating-label { font-size: 13px; font-weight: 700; text-transform: uppercase; letter-spacing: .06em; color: var(--text-secondary); margin-left: 6px; }\n.verdict-label { font-size: 26px; margin: 8px 0 6px; }\n.zone-red .rating-num, .zone-red .verdict-label { color: #B91C1C; }\n.zone-yellow .rating-num { color: #B45309; } .zone-yellow .verdict-label { color: #92400E; }\n.zone-green .rating-num, .zone-green .verdict-label { color: var(--emerald-deep); }\n.verdict-action { font-size: 16px; }\n.why { background: var(--off-white); border-left: 4px solid var(--emerald); padding: 10px 14px; border-radius: 6px; margin-top: 10px; }\n\n/* At a glance */\n.glance { display: grid; grid-template-columns: repeat(5, minmax(0, 1fr)); gap: 10px; padding: 20px 40px 8px; }\n.g-tile { background: var(--off-white); border-radius: 10px; padding: 12px; display: flex; flex-direction: column; }\n.g-num { font-family: var(--font-display); font-size: 26px; font-weight: 800; }\n.g-num small { font-size: 14px; color: var(--text-muted); }\n.g-label { font-size: 12px; color: var(--text-secondary); line-height: 1.3; }\n.g-bad .g-num { color: #B91C1C; }\n\n/* Sections */\n.r-sec { padding: 24px 40px; border-top: 1px solid var(--rule); }\n.r-h { font-size: 22px; margin-bottom: 6px; }\n.r-h-gap { margin-top: 28px; }\n.r-h3 { font-size: 16px; margin: 18px 0 8px; }\n.r-lede { color: var(--text-secondary); margin-bottom: 14px; }\n.note { font-size: 13px; color: var(--text-muted); margin-top: 8px; }\n\n/* Action plan */\n.priorities { list-style: none; margin: 0; padding: 0; display: grid; gap: 12px; }\n.prio { display: grid; grid-template-columns: 44px 1fr; gap: 14px; padding: 16px; border: 1px solid var(--rule);\n  border-left: 5px solid var(--emerald); border-radius: 10px; background: #fff; break-inside: avoid; }\n.prio-rethink, .prio-resolve { border-left-color: #DC2626; }\n.prio-num { width: 40px; height: 40px; border-radius: 50%; background: var(--ink); color: #fff; font-weight: 800; font-size: 18px;\n  display: inline-flex; align-items: center; justify-content: center; }\n.prio-title { font-size: 17px; margin-bottom: 6px; }\n.prio-why, .prio-how { font-size: 14px; }\n.prio-meta { display: flex; flex-wrap: wrap; gap: 4px 18px; font-size: 13px; color: var(--text-secondary); margin: 0; }\n.plan, .stages { width: 100%; border-collapse: collapse; font-size: 13px; }\n.plan th, .plan td, .stages th, .stages td { text-align: left; vertical-align: top; padding: 8px; border-bottom: 1px solid var(--rule); }\n.plan thead th, .stages thead th { font-size: 11px; text-transform: uppercase; letter-spacing: .05em; color: var(--text-muted); }\n.stages tbody th { font-weight: 600; }\n.core { font-size: 10px; font-weight: 700; text-transform: uppercase; color: var(--emerald-deep); background: var(--emerald-pale);\n  padding: 1px 6px; border-radius: 999px; }\n.st-passed .status, .st-complete .status { color: var(--emerald-deep); }\n.st-failed .status { color: #B91C1C; }\n.st-unproven .status, .st-in_progress .status { color: #92400E; }\n\n/* Charts */\n.fig { margin: 0; }\n.chart { width: 100%; height: auto; display: block; font-family: var(--font); }\n\n/* Findings */\n.cols { display: grid; grid-template-columns: repeat(3, minmax(0, 1fr)); gap: 14px; }\n.col { background: var(--off-white); border-radius: 10px; padding: 12px 14px; border-top: 4px solid var(--slate-muted); }\n.col-good { border-top-color: var(--emerald); } .col-bad { border-top-color: #DC2626; } .col-open { border-top-color: #F59E0B; }\n.col .r-h3 { margin-top: 0; }\n.col ul, .change { margin: 0; padding-left: 18px; font-size: 14px; }\n.col li, .change li { margin-bottom: 6px; }\n.founder dt { font-weight: 700; margin-top: 8px; }\n.founder dd { margin: 2px 0 0; white-space: pre-wrap; }\n\n.method { font-size: 14px; color: var(--text-secondary); }\n.r-foot { background: var(--ink); color: var(--slate-muted); font-size: 12px; padding: 14px 40px; border-top: 3px solid var(--emerald); }\n\n/* Phones */\n@media (max-width: 720px) {\n  .report { margin: 0; border-radius: 0; }\n  .cover, .verdict-panel, .glance, .r-sec, .r-foot { padding-left: 16px; padding-right: 16px; }\n  .cover-title { font-size: 26px; }\n  .verdict-panel { grid-template-columns: 1fr; }\n  .glance { grid-template-columns: repeat(2, minmax(0, 1fr)); }\n  .cols { grid-template-columns: 1fr; }\n  .prio { grid-template-columns: 1fr; }\n  .plan thead { display: none; }\n  .plan tr, .plan td { display: block; border: 0; padding: 2px 0; }\n  .plan tr { border-bottom: 1px solid var(--rule); padding: 8px 0; }\n  .stages thead { display: none; }\n  .stages tr, .stages th, .stages td { display: block; border: 0; padding: 2px 0; }\n  .stages tr { border-bottom: 1px solid var(--rule); padding: 8px 0; }\n}\n\n/* Print: clean pages, colours kept */\n@media print {\n  @page { margin: 14mm; }\n  body { background: #fff; font-size: 11pt; -webkit-print-color-adjust: exact; print-color-adjust: exact; }\n  .no-print { display: none !important; }\n  .report { max-width: none; margin: 0; box-shadow: none; border-radius: 0; }\n  .r-page { break-before: page; }\n  .r-sec, .prio, .col, .fig, tr { break-inside: avoid; }\n  .glance { grid-template-columns: repeat(5, minmax(0, 1fr)); }\n  a { color: inherit; text-decoration: none; }\n}\n";
